-- Checkpoint 246 / V-03: append-only Beschwerdeakte. Lokaler additiver Entwurf, nicht produktiv ausgeführt.
CREATE TABLE IF NOT EXISTS public.qm_complaints(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,
 scope text NOT NULL CHECK(scope IN('client','facility')),client_id uuid REFERENCES public.clients(id) ON DELETE RESTRICT,source_portal_request_id uuid,
 concern text NOT NULL CHECK(length(btrim(concern))>=5),received_at timestamptz NOT NULL,received_channel text NOT NULL CHECK(received_channel IN('letter','email','portal','phone','in_person','other')),
 complainant_kind text NOT NULL CHECK(complainant_kind IN('client','representative','anonymous','employee','other')),complainant_reference text,
 assigned_recipient_id uuid NOT NULL,assigned_recipient_name text NOT NULL CHECK(btrim(assigned_recipient_name)<>''),assigned_recipient_role text NOT NULL CHECK(btrim(assigned_recipient_role)<>''),due_at timestamptz NOT NULL CHECK(due_at>received_at),
 recorded_at timestamptz NOT NULL,recorded_by uuid NOT NULL REFERENCES auth.users(id),recorded_by_name text NOT NULL CHECK(btrim(recorded_by_name)<>''),request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),
 CHECK((scope='client' AND client_id IS NOT NULL) OR(scope='facility' AND client_id IS NULL)),CHECK(complainant_kind<>'anonymous' OR complainant_reference IS NULL),UNIQUE(tenant_id,client_request_id),UNIQUE(tenant_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_complaint_events(
 id uuid PRIMARY KEY,client_request_id uuid NOT NULL,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,complaint_id uuid NOT NULL REFERENCES public.qm_complaints(id) ON DELETE RESTRICT,sequence_no integer NOT NULL CHECK(sequence_no>=1),
 event_kind text NOT NULL CHECK(event_kind IN('investigation','response','closure','reopened')),occurred_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL CHECK(recorded_at>=occurred_at),actor_id uuid NOT NULL REFERENCES auth.users(id),actor_name text NOT NULL CHECK(btrim(actor_name)<>''),summary text NOT NULL CHECK(length(btrim(summary))>=5),
 response_recipient text,response_channel text CHECK(response_channel IN('letter','email','portal','phone','in_person')),result_code text CHECK(result_code IN('resolved','partially_resolved','not_resolved','withdrawn')),result_summary text,result_sha256 text CHECK(result_sha256~'^[0-9a-f]{64}$'),references_event_ids uuid[] NOT NULL DEFAULT '{}',request_fingerprint text NOT NULL CHECK(request_fingerprint~'^[0-9a-f]{32}$'),
 CHECK((event_kind='response')=(response_recipient IS NOT NULL AND response_channel IS NOT NULL)),CHECK((event_kind='closure')=(result_code IS NOT NULL AND btrim(result_summary)<>'' AND result_sha256 IS NOT NULL)),UNIQUE(tenant_id,client_request_id),UNIQUE(complaint_id,sequence_no),UNIQUE(complaint_id,id)
);
CREATE TABLE IF NOT EXISTS public.qm_complaint_event_evidence(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE CASCADE,complaint_id uuid NOT NULL REFERENCES public.qm_complaints(id) ON DELETE RESTRICT,event_id uuid NOT NULL REFERENCES public.qm_complaint_events(id) ON DELETE RESTRICT,position_no integer NOT NULL CHECK(position_no>=1),
 source_type text NOT NULL CHECK(source_type IN('portal_request','care_record','qm_document_version','communication','other')),source_entity_id uuid NOT NULL,source_version_id uuid,record_locator text NOT NULL CHECK(btrim(record_locator)<>''),source_sha256 text NOT NULL CHECK(source_sha256~'^[0-9a-f]{64}$'),UNIQUE(event_id,position_no),UNIQUE(event_id,id)
);
ALTER TABLE public.qm_complaints ENABLE ROW LEVEL SECURITY;ALTER TABLE public.qm_complaint_events ENABLE ROW LEVEL SECURITY;ALTER TABLE public.qm_complaint_event_evidence ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.qm_complaints,public.qm_complaint_events,public.qm_complaint_event_evidence FROM PUBLIC,anon,authenticated;GRANT SELECT ON public.qm_complaints,public.qm_complaint_events,public.qm_complaint_event_evidence TO authenticated;
DROP POLICY IF EXISTS qm_complaints_read ON public.qm_complaints;CREATE POLICY qm_complaints_read ON public.qm_complaints FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_complaint_events_read ON public.qm_complaint_events;CREATE POLICY qm_complaint_events_read ON public.qm_complaint_events FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
DROP POLICY IF EXISTS qm_complaint_event_evidence_read ON public.qm_complaint_event_evidence;CREATE POLICY qm_complaint_event_evidence_read ON public.qm_complaint_event_evidence FOR SELECT TO authenticated USING(tenant_id=public.current_tenant_id() AND public.has_permission('qm.view'));
CREATE OR REPLACE FUNCTION care_private.protect_qm_complaint_history()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN RAISE EXCEPTION 'Beschwerdeakte bleibt append-only.' USING ERRCODE='42501';END$$;
DROP TRIGGER IF EXISTS protect_qm_complaints ON public.qm_complaints;CREATE TRIGGER protect_qm_complaints BEFORE UPDATE OR DELETE ON public.qm_complaints FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_complaint_history();
DROP TRIGGER IF EXISTS protect_qm_complaint_events ON public.qm_complaint_events;CREATE TRIGGER protect_qm_complaint_events BEFORE UPDATE OR DELETE ON public.qm_complaint_events FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_complaint_history();
DROP TRIGGER IF EXISTS protect_qm_complaint_event_evidence ON public.qm_complaint_event_evidence;CREATE TRIGGER protect_qm_complaint_event_evidence BEFORE UPDATE OR DELETE ON public.qm_complaint_event_evidence FOR EACH ROW EXECUTE FUNCTION care_private.protect_qm_complaint_history();

CREATE OR REPLACE FUNCTION public.record_qm_complaint_case(p_payload jsonb,p_client_request_id uuid)RETURNS public.qm_complaints LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t uuid:=public.current_tenant_id();actor uuid:=auth.uid();actor_name text:=public.clinical_actor_name();actual_time timestamptz:=clock_timestamp();result public.qm_complaints;prior public.qm_complaints;root_fp text;event_item record;evidence_item record;event_fp text;seq integer;last_kind text;last_at timestamptz;last_reopen integer:=0;investigation_count integer;response_count integer;refs uuid[];client uuid;portal uuid;
BEGIN
 IF t IS NULL OR actor IS NULL OR NOT public.has_permission('qm.create_audit') THEN RAISE EXCEPTION 'Keine Berechtigung.' USING ERRCODE='42501';END IF;
 IF p_payload IS NULL OR p_client_request_id IS NULL OR p_payload->>'clientRequestId' IS DISTINCT FROM p_client_request_id::text OR COALESCE(p_payload->>'complaintId','')='' OR btrim(COALESCE(p_payload->>'concern',''))='' OR jsonb_typeof(p_payload->'events')<>'array' OR COALESCE(p_payload->>'recordedAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' THEN RAISE EXCEPTION 'Beschwerde ist unvollständig.' USING ERRCODE='23514';END IF;
 client:=NULLIF(p_payload->>'clientId','')::uuid;portal:=NULLIF(p_payload->>'sourcePortalRequestId','')::uuid;
 IF(p_payload->>'tenantId')::uuid IS DISTINCT FROM t OR COALESCE(p_payload->>'scope','') NOT IN('client','facility') OR(p_payload->>'scope'='client' AND client IS NULL)OR(p_payload->>'scope'='facility' AND client IS NOT NULL)OR(client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clients WHERE tenant_id=t AND id=client))THEN RAISE EXCEPTION 'Mandant oder Pflegefall der Beschwerde ist widersprüchlich.' USING ERRCODE='23514';END IF;
 IF portal IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.portal_requests WHERE tenant_id=t AND id=portal AND request_type='beschwerde' AND client_id IS NOT DISTINCT FROM client)THEN RAISE EXCEPTION 'Portalbeschwerde fehlt oder gehört nicht zum Umfang.' USING ERRCODE='23503';END IF;
 root_fp:=md5(jsonb_build_object('root',p_payload-'events')::text);PERFORM pg_advisory_xact_lock(hashtext(t::text),hashtext((p_payload->>'complaintId')));
 SELECT*INTO prior FROM public.qm_complaints WHERE tenant_id=t AND id=(p_payload->>'complaintId')::uuid;
 IF FOUND THEN IF prior.request_fingerprint IS DISTINCT FROM root_fp OR prior.client_request_id IS DISTINCT FROM p_client_request_id THEN RAISE EXCEPTION 'Beschwerdeidentität wurde anders verwendet.' USING ERRCODE='40001';END IF;result:=prior;
 ELSE
  IF(p_payload->>'recordedBy')::uuid IS DISTINCT FROM actor OR btrim(p_payload->>'recordedByName') IS DISTINCT FROM btrim(actor_name) OR(p_payload->>'receivedAt')::timestamptz>(p_payload->>'recordedAt')::timestamptz OR(p_payload->>'recordedAt')::timestamptz>actual_time OR(p_payload->>'dueAt')::timestamptz<=(p_payload->>'receivedAt')::timestamptz THEN RAISE EXCEPTION 'Eingang, Frist oder Erfassungsidentität ist widersprüchlich.' USING ERRCODE='23514';END IF;
  INSERT INTO public.qm_complaints(id,client_request_id,tenant_id,scope,client_id,source_portal_request_id,concern,received_at,received_channel,complainant_kind,complainant_reference,assigned_recipient_id,assigned_recipient_name,assigned_recipient_role,due_at,recorded_at,recorded_by,recorded_by_name,request_fingerprint)
  VALUES((p_payload->>'complaintId')::uuid,p_client_request_id,t,p_payload->>'scope',client,portal,btrim(p_payload->>'concern'),(p_payload->>'receivedAt')::timestamptz,p_payload->>'receivedChannel',p_payload->>'complainantKind',NULLIF(btrim(COALESCE(p_payload->>'complainantReference','')),''),(p_payload->>'assignedRecipientId')::uuid,btrim(p_payload->>'assignedRecipientName'),btrim(p_payload->>'assignedRecipientRole'),(p_payload->>'dueAt')::timestamptz,actual_time,actor,actor_name,root_fp)RETURNING*INTO result;
 END IF;
 SELECT COALESCE(max(sequence_no),0),max(recorded_at),(array_agg(event_kind ORDER BY sequence_no DESC))[1] INTO seq,last_at,last_kind FROM public.qm_complaint_events WHERE complaint_id=result.id;
 SELECT COALESCE(max(sequence_no),0)INTO last_reopen FROM public.qm_complaint_events WHERE complaint_id=result.id AND event_kind='reopened';
 FOR event_item IN SELECT value,ordinality FROM jsonb_array_elements(p_payload->'events')WITH ORDINALITY LOOP
  event_fp:=md5(event_item.value::text);IF EXISTS(SELECT 1 FROM public.qm_complaint_events WHERE tenant_id=t AND client_request_id=(event_item.value->>'clientRequestId')::uuid AND request_fingerprint=event_fp)THEN CONTINUE;END IF;
  IF EXISTS(SELECT 1 FROM public.qm_complaint_events WHERE tenant_id=t AND client_request_id=(event_item.value->>'clientRequestId')::uuid) OR COALESCE(event_item.value->>'occurredAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}(Z|\+00:00)$' OR(event_item.value->>'occurredAt')::timestamptz>actual_time OR(last_at IS NOT NULL AND(event_item.value->>'occurredAt')::timestamptz<last_at)THEN RAISE EXCEPTION 'Beschwerdeereignis ist doppelt oder zeitlich widersprüchlich.' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(event_item.value->'evidence')<>'array' OR jsonb_typeof(event_item.value->'referencesEventIds')<>'array' THEN RAISE EXCEPTION 'Beschwerdeereignis benötigt Beleg- und Referenzlisten.' USING ERRCODE='23514';END IF;
  refs:=ARRAY(SELECT jsonb_array_elements_text(event_item.value->'referencesEventIds')::uuid);investigation_count:=(SELECT count(*) FROM public.qm_complaint_events WHERE complaint_id=result.id AND sequence_no>last_reopen AND event_kind='investigation');response_count:=(SELECT count(*) FROM public.qm_complaint_events WHERE complaint_id=result.id AND sequence_no>last_reopen AND event_kind='response');
  IF event_item.value->>'kind'='investigation' AND jsonb_array_length(event_item.value->'evidence')<1 THEN RAISE EXCEPTION 'Untersuchung benötigt einen konkreten Beleg.' USING ERRCODE='23514';END IF;
  IF last_kind='closure' AND event_item.value->>'kind'<>'reopened' THEN RAISE EXCEPTION 'Geschlossene Beschwerde benötigt eine ausdrückliche Wiederaufnahme.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='response' AND(jsonb_array_length(event_item.value->'evidence')<1 OR btrim(COALESCE(event_item.value->>'responseRecipient',''))='' OR COALESCE(event_item.value->>'responseChannel','') NOT IN('letter','email','portal','phone','in_person') OR NOT EXISTS(SELECT 1 FROM public.qm_complaint_events WHERE complaint_id=result.id AND sequence_no>last_reopen AND event_kind='investigation' AND id=ANY(refs)))THEN RAISE EXCEPTION 'Antwort benötigt Untersuchung, Empfänger, Kanal und Beleg.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='closure' AND(NOT public.has_permission('qm.close_audit') OR investigation_count<1 OR response_count<1 OR COALESCE(event_item.value->>'resultCode','') NOT IN('resolved','partially_resolved','not_resolved','withdrawn') OR btrim(COALESCE(event_item.value->>'resultSummary',''))='' OR COALESCE(event_item.value->>'resultSha256','')!~'^[0-9a-f]{64}$' OR NOT EXISTS(SELECT 1 FROM public.qm_complaint_events WHERE complaint_id=result.id AND sequence_no>last_reopen AND event_kind='investigation' AND id=ANY(refs)) OR NOT EXISTS(SELECT 1 FROM public.qm_complaint_events WHERE complaint_id=result.id AND sequence_no>last_reopen AND event_kind='response' AND id=ANY(refs)))THEN RAISE EXCEPTION 'Abschluss benötigt Untersuchung, Antwort, Ergebnisbeleg und Schließrecht.' USING ERRCODE='42501';END IF;
  IF event_item.value->>'kind'='closure' AND jsonb_array_length(event_item.value->'evidence')<1 THEN RAISE EXCEPTION 'Abschluss benötigt einen eigenen Ergebnisbeleg.' USING ERRCODE='23514';END IF;
  IF event_item.value->>'kind'='reopened' AND(last_kind<>'closure' OR jsonb_array_length(event_item.value->'evidence')<>0)THEN RAISE EXCEPTION 'Nur eine geschlossene Beschwerde kann ohne erfundenen Abschlussbeleg wiederaufgenommen werden.' USING ERRCODE='23514';END IF;
  seq:=seq+1;INSERT INTO public.qm_complaint_events(id,client_request_id,tenant_id,complaint_id,sequence_no,event_kind,occurred_at,recorded_at,actor_id,actor_name,summary,response_recipient,response_channel,result_code,result_summary,result_sha256,references_event_ids,request_fingerprint)
  VALUES((event_item.value->>'eventId')::uuid,(event_item.value->>'clientRequestId')::uuid,t,result.id,seq,event_item.value->>'kind',(event_item.value->>'occurredAt')::timestamptz,actual_time,actor,actor_name,btrim(event_item.value->>'summary'),NULLIF(btrim(COALESCE(event_item.value->>'responseRecipient','')),''),NULLIF(event_item.value->>'responseChannel',''),NULLIF(event_item.value->>'resultCode',''),NULLIF(btrim(COALESCE(event_item.value->>'resultSummary','')),''),NULLIF(event_item.value->>'resultSha256',''),refs,event_fp);
  FOR evidence_item IN SELECT value,ordinality FROM jsonb_array_elements(event_item.value->'evidence')WITH ORDINALITY LOOP
   IF btrim(COALESCE(evidence_item.value->>'recordLocator',''))='' OR COALESCE(evidence_item.value->>'sourceSha256','')!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Beschwerdebeleg ist unvollständig.' USING ERRCODE='23514';END IF;
   INSERT INTO public.qm_complaint_event_evidence(id,tenant_id,complaint_id,event_id,position_no,source_type,source_entity_id,source_version_id,record_locator,source_sha256)VALUES((evidence_item.value->>'evidenceId')::uuid,t,result.id,(event_item.value->>'eventId')::uuid,evidence_item.ordinality,evidence_item.value->>'sourceType',(evidence_item.value->>'sourceEntityId')::uuid,NULLIF(evidence_item.value->>'sourceVersionId','')::uuid,btrim(evidence_item.value->>'recordLocator'),evidence_item.value->>'sourceSha256');
  END LOOP;last_kind:=event_item.value->>'kind';last_at:=(event_item.value->>'occurredAt')::timestamptz;IF last_kind='reopened'THEN last_reopen:=seq;END IF;
 END LOOP;
 INSERT INTO public.care_audit_events(tenant_id,entity_type,entity_id,action,summary,after_data,actor_id,actor_name)VALUES(t,'qm_complaint',result.id,'complaint_history_recorded','Beschwerdeakte append-only fortgeschrieben; Abschluss nur mit Untersuchung, Antwort und Ergebnis.',to_jsonb(result),actor,actor_name);RETURN result;
END$$;
REVOKE ALL ON FUNCTION public.record_qm_complaint_case(jsonb,uuid)FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.record_qm_complaint_case(jsonb,uuid)TO authenticated;
